head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxByteLength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 바이트 길이를 설정합니다.",
    "validation" : [
        "입력 가능한 최대 바이트 길이를 양의 정수로 설정합니다.",
        "최대 바이트 길이를 초과하면 초과분이 자동으로 잘립니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 입력을 제한하지 않습니다.",
        "config.xml 의 WebSquare/byteCheckEncoding/@value 가 'euc-kr' 인 경우 한글 1 자는 2 바이트로 계산됩니다.",        
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



// target1 : dataType=text, maxByteLength=6, 입력값=가나다라마바사, 기대값=가나다 (euc-kr 기준)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바사");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2 : dataType=text, maxByteLength 미설정, 입력값=가나다라마바사, 기대값=가나다라마바사
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바사");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3 : dataType=number, maxByteLength=6, 입력값=123456789, 기대값=123456
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue(123456789);
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
};

// target4 : dataType=float, maxByteLength=8, 입력값=123456.789, 기대값=123456.7
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue(123456.789);
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
};


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 5; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 5; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};
